    void contextBudget(Selection selection){
        TextView text=label(tr("Считаем…","Calculating…"),14);AlertDialog dialog=WorkspaceDialogs.builder(activity).setTitle(tr("Бюджет контекста","Context budget")).setView(scroll(text)).setPositiveButton(tr("Назад","Back"),null).create();dialog.show();
        worker.execute(()->{try{WorkspaceStore.Session p=selection.profile();JSONObject model=files.find(selection.model);boolean nativeRt=p.localProtocol.equals(LocalAiLiteRt.NATIVE)&&LocalAiLiteRt.supported(model);String behavior=LocalAiPrompts.behavior(activity,p),instructions=nativeRt?LocalAiLiteRt.prompt(p,p.localBehavior):behavior+"\n"+LocalAiPrompts.permissions(p);String schemas=nativeRt?LocalAiLiteRt.schemas(p,model).toString():"";JSONArray h=selection.chat.isEmpty()?new JSONArray():LocalAiAgent.context(files.history(selection.chat));
            int fixed=(int)Math.ceil(LocalAiContext.weight(instructions+schemas));String result=tr("Предварительная оценка (без точного токенизатора):\nКонтекст: ","Preview estimate (without exact tokenizer):\nContext: ")+selection.context+tr("\nИнструкции и схемы: ","\nInstructions and schemas: ")+fixed+tr("\nПереписка, запросы и оформление: ","\nConversation, requests and formatting: ")+Math.max(0,LocalAiContext.estimate(h,instructions+schemas)-fixed)+tr("\nВыбранный резерв ответа: ","\nRequested reply reserve: ")+selection.maxTokens+tr("\nОстаток по оценке: ","\nEstimated remaining: ")+(selection.context-64-selection.maxTokens-LocalAiContext.estimate(h,instructions+schemas))+tr("\n\nРезерв может автоматически уменьшаться. Текущий запрос не обрезается. Точный состав llama.cpp доступен после запроса, когда движок загружен.","\n\nReply reserve may be reduced automatically. The current request is not truncated. Exact llama.cpp input composition is available after a request with the engine loaded.");
            ui(()->{if(!dialog.isShowing())return;for(Panel panel:panels.values())if(!selection.chat.isEmpty()&&selection.chat.equals(panel.profile.localChat)){text.setText(result+tr("\n\nПоследний запрос сессии:\n","\n\nLast session request:\n")+panel.timing.budgetReport(WorkspaceLanguage.code(activity).equals("ru")));return;}text.setText(result);});
        }catch(Exception e){ui(()->{if(dialog.isShowing())text.setText(failureText(e));});}});
    }
