        final LinearLayout root=column(),messages=column();final ScrollView historyScroll=scroll(messages);
        final ActivityDots activityDots=new ActivityDots();
        final TextView status=label("",12),start;final ProgressBar progress=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);
        final AtomicBoolean cancelled=new AtomicBoolean();final LocalAiRemote engine=new LocalAiRemote(activity.getApplicationContext());
        volatile LocalAiTools tools;
        volatile String loadedEngineType="",savedTimingRu="",savedTimingEn="";final LocalAiTiming timing=new LocalAiTiming();volatile String stageName="preparation";volatile boolean awaitingText;MessageView pendingAnswer;
        volatile boolean literalAnswer;
