        void updateAnswer(MessageView answer,String value){if(closed||!root.isShown())return;if(value.isEmpty()){awaitingText=true;answer.pending();}else if(literalAnswer){awaitingText=false;answer.literal(value);}else{awaitingText=LocalAiToolText.preview(LocalAiText.split(value).answer).text.trim().isEmpty();if(awaitingText)answer.pending();else answer.content(value,false,true);}scrollToLatest();}

        void chatMenu(){if(busy||historyLoading){error(new IllegalStateException(tr("Сначала дождитесь завершения текущей операции","Stop the current operation first")));return;}chooseChat(this::changeChat);}
        void newChat(){if(busy||historyLoading){error(new IllegalStateException(tr("Дождитесь завершения или остановите текущую операцию","Wait for completion or stop the current operation")));return;}changeChat("");}
        void changeChat(String id){WorkspaceStore.Session check=profile.copy();check.localChat=id;if(WorkspaceChatHistories.deleting(check)||closingChats.contains(id)){error(new IllegalStateException("History deletion/close in progress"));return;}if(busy)return;busy=true;worker.execute(()->{try{JSONArray h=id.isEmpty()?new JSONArray():files.history(id);ui(()->{profile.localChat=id;history=h;save.run();busy=false;drawHistory();updateLabel();});}catch(Exception e){ui(()->{busy=false;updateLabel();error(e);});}});}
        void readHistory(){historyLoading=true;final String chat=profile.localChat;worker.execute(()->{try{JSONArray h=chat.isEmpty()?new JSONArray():files.history(chat);try{JSONObject prior=new JSONObject(LocalAiFiles.read(new java.io.FileInputStream(timingFile()),65536));savedTimingRu=prior.optString("ru");savedTimingEn=prior.optString("en");}catch(Exception ignored){}try{JSONObject prior=new JSONObject(LocalAiFiles.read(new java.io.FileInputStream(benchmarkFile()),262144));savedBenchmarkRu=prior.optString("ru");savedBenchmarkEn=prior.optString("en");}catch(Exception ignored){}ui(()->{if(chat.equals(profile.localChat)){history=h;drawHistory();}historyLoading=false;updateLabel();});}catch(Exception e){ui(()->{historyLoading=false;error(e);});}});}
