        void saveTiming(){if(timing.paused)return;try{savedTimingRu=timing.report(true);savedTimingEn=timing.report(false);LocalAiFiles.atomic(timingFile(),new JSONObject().put("ru",timing.report(true)).put("en",timing.report(false)).toString());}catch(Exception ignored){}}
        String timingReport(){if(timing.phase.equals("idle")){timing.model=profile.localModel;timing.backend=profile.localBackend;timing.context=profile.localContext;timing.answer=profile.localMaxTokens;}boolean ru=WorkspaceLanguage.code(activity).equals("ru");String saved=ru?savedTimingRu:savedTimingEn;return timing.phase.equals("idle")&&!saved.isEmpty()?saved:timing.report(ru);}
        void setPhase(String phase){stageName=phase;timing.phase(phase);ui(()->{if(busy&&awaitingText&&pendingAnswer!=null)pendingAnswer.pending();});}
        void diagnostics(){DiagnosticsPanel.show((com.termux.app.TermuxActivity)activity,new DiagnosticsPanel.Source(){
            boolean ru(){return WorkspaceLanguage.code(activity).equals("ru");}public String actionLabel(){return tr("Тест обработки входа","Input processing test");}public void action(){benchmarkMenu();}public String title(){return tr("Диагностика локального ИИ","Local AI diagnostics");}public String id(){return profile.id;}public void refresh(){}public String summary(){return timingReport();}public String events(){return timing.eventsReport(ru());}public String report(){return timingReport();}public int bytes(){return report().length()*2;}public int dropped(){return 0;}public boolean paused(){return timing.paused;}public void paused(boolean value){timing.paused=value;activity.getSharedPreferences("local-ai-diagnostics",0).edit().putBoolean(profile.id,value).apply();}public boolean hasMode(){return false;}public boolean extended(){return false;}public void extended(boolean value){}
        });}
        File benchmarkFile(){File folder=new File(files.root,"diagnostics");folder.mkdirs();return new File(folder,"bench-"+LocalAiFiles.safeId(profile.id)+".json");}
        void benchmarkMenu(){
            if(profile.localCompute.equals("gpu")){error(new IllegalStateException(tr("Этот тест сравнивает CPU. Выберите CPU в режиме работы; GPU проверяйте по диагностике обычного запроса.","This test compares CPU. Select CPU in Operating mode; inspect ordinary request diagnostics for GPU.")));return;}
            if(benchmarking){showBenchmark();return;}if(busy||historyLoading){error(new IllegalStateException(tr("Сначала загрузите llama.cpp-модель и дождитесь завершения текущей операции.","Load a llama.cpp model and finish the current operation first.")));return;}
            for(Panel other:panels.values())if(other!=this&&other.busy){error(new IllegalStateException(tr("Другой локальный ИИ занят.","Another local AI is busy.")));return;}
            WorkspaceDialogs.builder(activity).setTitle(tr("Тест обработки входа","Input processing test")).setItems(new String[]{LocalAiBenchmark.name(0,WorkspaceLanguage.code(activity).equals("ru")),LocalAiBenchmark.name(1,WorkspaceLanguage.code(activity).equals("ru")),LocalAiBenchmark.name(2,WorkspaceLanguage.code(activity).equals("ru")),tr("Последний отчёт","Last report")},(d,w)->{if(w==3){showBenchmark();return;}if(!loaded||!loadedEngineType.startsWith("llama /")){error(new IllegalStateException(tr("Сначала загрузите llama.cpp-модель.","Load a llama.cpp model first.")));return;}WorkspaceDialogs.builder(activity).setTitle(LocalAiBenchmark.name(w,WorkspaceLanguage.code(activity).equals("ru"))).setMessage(tr("Тест использует синтетические токены и временные контексты, без истории и кэша чата. Несколько прогонов могут занять минуты. Чат сохранится. Во время теста локальный ИИ занят; остановка доступна в отчёте. Начать?","Uses synthetic tokens and temporary contexts, without chat history/cache. Several trials may take minutes. Chat is kept. Local AI is busy during the test; Stop is available in the report. Start?")).setPositiveButton(tr("Начать","Start"),(a,b)->startBenchmark(w)).setNegativeButton(tr("Отмена","Cancel"),null).show();}).setNegativeButton(tr("Отмена","Cancel"),null).show();
        }
        void startBenchmark(int mode){if(busy||!loaded)return;for(Panel other:panels.values())if(other!=this&&other.busy)return;engine.prepareBenchmark();benchmark.begin(profile.localModel,timingBackend(),mode);benchmarking=true;busy=true;updateLabel();showBenchmark();worker.execute(()->{try{engine.benchmark(mode,new LocalAiEngine.Output(){public void text(String text){}public void performance(String json){benchmark.accept(json);}});benchmark.finish(benchmark.stopRequested?"stopped":"completed","");}catch(Exception e){benchmark.finish(benchmark.stopRequested?"stopped":"failed",e.getClass().getSimpleName());}finally{try{savedBenchmarkRu=benchmark.report(true);savedBenchmarkEn=benchmark.report(false);LocalAiFiles.atomic(benchmarkFile(),new JSONObject().put("ru",savedBenchmarkRu).put("en",savedBenchmarkEn).toString());}catch(Exception ignored){}ui(()->{benchmarking=false;busy=false;if(panels.get(profile.id)!=this)return;if(engine.backend.isEmpty())loaded=false;updateLabel();});}});}
